/**
 * This is the comms subsystem of the runtime.
 * @mixin @node-red/runtime_comms
 */

/**
 * A WebSocket connection between the runtime and the editor.
 * @typedef CommsConnection
 * @type {object}
 * @property {string} session - a unique session identifier
 * @property {Object} user - the user associated with the connection
 * @property {Function} send - publish a message to the connection
 */


var runtime;
var retained = {};
var connections = [];
var subscriptions = {};

const events = require("@node-red/util").events;
const log = require("@node-red/util").log;

function handleCommsEvent(event) {
    publish(event.topic,event.data,event.retain);
}

function topicMatch(pattern,topic) {
    var re = new RegExp("^"+pattern.replace(/([\[\]\?\(\)\\\\$\^\*\.|])/g,"\\$1").replace(/\+/g,"[^/]+").replace(/\/#$/,"(\/.*)?")+"$");
    return re.test(topic);
}
function handleStatusEvent(event) {
    if (!event.status) {
        delete retained["status/"+event.id]
    } else if (!event.status.text && !event.status.fill && !event.status.shape) {
        if (retained["status/"+event.id]) {
            publish("status/"+event.id,{},false);
        }
    } else {
        var status = {
            text: event.status.text,
            fill: event.status.fill,
            shape: event.status.shape
        };
        publish("status/"+event.id,status,true);
    }
}
function handleRuntimeEvent(event) {
    runtime.log.trace("runtime event: "+JSON.stringify(event));
    publish("notification/"+event.id,event.payload||{},event.retain);
}
function handleEventLog(event) {
    var type = event.payload.type;
    var id = event.id;
    if (event.payload.data) {
        var data = event.payload.data;
        if (data.endsWith('\n')) {
            data = data.substring(0,data.length-1);
        }
        var lines = data.split(/\n/);
        lines.forEach(line => {
            runtime.log.debug((type?("["+type+"] "):"")+line)
        })
    }
    publish("event-log/"+event.id,event.payload||{});
}

function publish(topic,data,retain,options) {
    options = options||{};
    var hasTarget = (options.session || options.excludeSession);
    if (!hasTarget) {
        if (retain) {
            retained[topic] = data;
        } else {
            delete retained[topic];
        }
    }
    connections.forEach(connection => {
        if (options.session) {
            if (connection.session === options.session) {
                connection.send(topic,data);
            }
        } else if (options.excludeSession) {
            if (connection.session !== options.excludeSession) {
                connection.send(topic,data);
            }
        } else {
            connection.send(topic,data);
        }
    });
}


var api = module.exports = {
    init: function(_runtime) {
        runtime = _runtime;
        connections = [];
        retained = {};
        subscriptions = {};
        events.removeListener("node-status",handleStatusEvent);
        events.on("node-status",handleStatusEvent);
        events.removeListener("runtime-event",handleRuntimeEvent);
        events.on("runtime-event",handleRuntimeEvent);
        events.removeListener("comms",handleCommsEvent);
        events.on("comms",handleCommsEvent);
        events.removeListener("event-log",handleEventLog);
        events.on("event-log",handleEventLog);
    },

    /**
    * Registers a new comms connection
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {CommsConnection} opts.client - the client connection
    * @return {Promise<Object>} - resolves when complete
    * @memberof @node-red/runtime_comms
    */
    addConnection: async function(opts) {
        connections.push(opts.client);
    },

    /**
    * Unregisters a comms connection
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {CommsConnection} opts.client - the client connection
    * @return {Promise<Object>} - resolves when complete
    * @memberof @node-red/runtime_comms
    */
    removeConnection: async function(opts) {
        for (var i=0;i<connections.length;i++) {
            if (connections[i] === opts.client) {
                connections.splice(i,1);
                break;
            }
        }
    },

    /**
    * Subscribes a comms connection to a given topic. Currently, all clients get
    * automatically subscribed to everything and cannot unsubscribe. Sending a subscribe
    * request will trigger retained messages to be sent.
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {CommsConnection} opts.client - the client connection
    * @param {String} opts.topic - the topic to subscribe to
    * @return {Promise<Object>} - resolves when complete
    * @memberof @node-red/runtime_comms
    */
    subscribe: async function(opts) {
        var re = new RegExp("^"+opts.topic.replace(/([\[\]\?\(\)\\\\$\^\*\.|])/g,"\\$1").replace(/\+/g,"[^/]+").replace(/\/#$/,"(\/.*)?")+"$");
        for (var t in retained) {
            if (re.test(t)) {
                opts.client.send(t,retained[t]);
            }
        }
    },

    /**
    * TODO: Unsubscribes a comms connection from a given topic
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {CommsConnection} opts.client - the client connection
    * @param {String} opts.topic - the topic to unsubscribe from
    * @return {Promise<Object>} - resolves when complete
    * @memberof @node-red/runtime_comms
    */
    unsubscribe: async function(opts) {},

    /**
    * Publishes a message to all connected editor clients.
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {String} opts.topic - the topic to publish to
    * @param {Object} opts.data - the message payload
    * @param {Boolean} opts.retain - whether to retain the message for newly connected clients
    * @param {String} opts.session - if set, only send the message to this client session
    * @param {String} opts.excludeSession - if set, send the message to all clients except this session
    * @return {Promise<Object>} - resolves when complete
    * @memberof @node-red/runtime_comms
    */
    publish: async function(opts) {
        publish(opts.topic,opts.data,opts.retain,{
            session: opts.session,
            excludeSession: opts.excludeSession
        });
    },

    /**
    * Handles a message received from an editor client. Dispatches it to any
    * runtime-side subscribers registered for the message topic.
    * @param {Object} opts
    * @param {String} opts.topic - the topic of the received message
    * @param {Object} opts.data - the message payload
    * @param {String} opts.session - the session id of the client that sent the message
    * @param {User} opts.user - the user the client is authenticated as
    * @return {Promise<Object>} - resolves when complete
    * @memberof @node-red/runtime_comms
    */
    receive: async function(opts) {
        for (var pattern in subscriptions) {
            if (subscriptions.hasOwnProperty(pattern) && topicMatch(pattern,opts.topic)) {
                var subscribers = subscriptions[pattern];
                for (var i=0;i<subscribers.length;i++) {
                    try {
                        subscribers[i](opts.topic,opts.data,{
                            session: opts.session,
                            user: opts.user
                        });
                    } catch(err) {
                        if (runtime) {
                            runtime.log.warn(log._("comms.error-subscribe",{message:err.toString()}));
                            runtime.log.warn(err.stack);
                        }
                    }
                }
            }
        }
    },

    /**
    * Subscribes a runtime component to messages sent from the editor.
    * @param {Object} opts
    * @param {String} opts.topic - the topic to subscribe to; may contain '+' and '#' wildcards
    * @param {Function} opts.callback - called as (topic, data, {session, user}) for each matching message
    * @return {Promise<Object>} - resolves when complete
    * @memberof @node-red/runtime_comms
    */
    subscribeMessages: async function(opts) {
        var topic = opts.topic;
        subscriptions[topic] = subscriptions[topic]||[];
        subscriptions[topic].push(opts.callback);
    },

    /**
    * Unsubscribes a runtime component from editor messages.
    * @param {Object} opts
    * @param {String} opts.topic - the topic that was subscribed to
    * @param {Function} opts.callback - the callback that was registered
    * @return {Promise<Object>} - resolves when complete
    * @memberof @node-red/runtime_comms
    */
    unsubscribeMessages: async function(opts) {
        var subscribers = subscriptions[opts.topic];
        if (subscribers) {
            for (var i=0;i<subscribers.length;i++) {
                if (subscribers[i] === opts.callback) {
                    subscribers.splice(i,1);
                    break;
                }
            }
            if (subscribers.length === 0) {
                delete subscriptions[opts.topic];
            }
        }
    }
};
